<script setup>import { computed,onMounted,reactive,ref } from 'vue';import { showSuccessToast } from 'vant';import { api } from '../api/ehr';import { useAuthStore } from '../stores/auth';const auth=useAuthStore(),items=ref([]),pending=ref([]),show=ref(false),form=reactive({leaveType:'年假',startTime:'',endTime:'',durationDays:1,reason:''});const canApprove=computed(()=>['ADMIN','HR'].includes(auth.user?.role));async function load(){items.value=await api.leaves();if(canApprove.value)pending.value=await api.pendingLeaves()}async function submit(){await api.createLeave({...form,durationDays:Number(form.durationDays)});show.value=false;showSuccessToast('申请已提交');load()}async function approve(id,approved){await api.approveLeave(id,{approved,comment:approved?'同意':'不同意'});showSuccessToast('审批完成');load()}const label={PENDING:'审批中',APPROVED:'已通过',REJECTED:'已拒绝',CANCELLED:'已撤销'};onMounted(load)</script>
<template><div class="page safe-top"><van-nav-bar title="请假审批" left-arrow @click-left="$router.back()" right-text="申请" @click-right="show=true"/><template v-if="canApprove&&pending.length"><h2 class="section-title">待我审批</h2><section v-for="item in pending" :key="item.id" class="card"><div class="leave-head"><b>{{item.applicantName}} · {{item.leaveType}}</b><span class="tag">{{item.durationDays}} 天</span></div><p>{{item.reason}}</p><div class="muted">{{item.startTime.replace('T',' ')}} 至 {{item.endTime.replace('T',' ')}}</div><div class="approval"><van-button size="small" @click="approve(item.id,false)">拒绝</van-button><van-button size="small" color="#7b4a35" @click="approve(item.id,true)">同意</van-button></div></section></template><h2 class="section-title">我的申请</h2><section v-for="item in items" :key="item.id" class="card"><div class="leave-head"><b>{{item.leaveType}} · {{item.durationDays}} 天</b><span class="status" :class="item.status.toLowerCase()">{{label[item.status]}}</span></div><p>{{item.reason}}</p><div class="muted">{{item.startTime.replace('T',' ').slice(0,16)}} 至 {{item.endTime.replace('T',' ').slice(0,16)}}</div></section><div v-if="!items.length" class="empty">暂无请假申请</div><van-popup v-model:show="show" position="bottom" round><div class="form"><h2>提交请假申请</h2><van-field v-model="form.leaveType" label="类型" is-link readonly/><van-radio-group v-model="form.leaveType" direction="horizontal"><van-radio name="年假">年假</van-radio><van-radio name="事假">事假</van-radio><van-radio name="病假">病假</van-radio></van-radio-group><van-field v-model="form.startTime" label="开始" type="datetime-local"/><van-field v-model="form.endTime" label="结束" type="datetime-local"/><van-field v-model="form.durationDays" label="天数" type="number"/><van-field v-model="form.reason" label="原因" type="textarea" rows="2"/><button class="action-btn" :disabled="!form.startTime||!form.endTime||!form.reason" @click="submit">提交申请</button></div></van-popup></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.leave-head{display:flex;justify-content:space-between}.card p{color:#52676e}.status{font-size:12px}.pending{color:#b37c26}.approved{color:#2b8d69}.rejected{color:#d04e4e}.approval{display:flex;justify-content:flex-end;gap:10px;margin-top:14px}.form{padding:18px 20px 32px}.form h2{margin:0 0 12px}.van-radio-group{padding:16px}.action-btn{margin-top:12px}</style>
